/// Read the explicit source profile for CLI routing; this does not admit a program.
pub fn language(source: &str) -> Result<&'static str, Error> {
    let lexed = mori_lexer::lex(source).map_err(|e| Error::new("lex", e.to_string()))?;
    let mut tokens = Vec::new();
    for i in 0..lexed.len() {
        let idx = TokenIdx::new(i);
        let span = lexed.span(idx, source);
        let raw = &source[span.start as usize..span.end as usize];
        let kind = lexed.kind(idx);
        tokens.push(Tok {
            text: if kind == TokenKind::String { mori_lexer::decode_string(raw) } else { raw.to_owned() },
            kind,
            start: span.start,
        });
    }
    let mut parser = Parser { tokens, pos: 0, program: Program {
        language: LANGUAGE.into(), semantics: SEMANTICS.into(), name: String::new(),
        states: vec![], assets: vec![], expressions: vec![], actions: vec![],
    }};
    parser.expect("language")?;
    let profile = parser.string()?;
    match profile.as_str() {
        LANGUAGE => Ok(LANGUAGE),
        crate::stage::LANGUAGE_2 => Ok(crate::stage::LANGUAGE_2),
        _ => Err(parser.error("profile", format!("Expected language \"{LANGUAGE}\"; found {profile:?}."))),
    }
}

/// Route by `mori_core::language`, then admit with the profile's own Core entry point.
pub fn admit_source(source: &str) -> Result<Admitted, CompileError> {
    let profile = mori_core::language(source).map_err(CompileError::Core)?;
    let source_sha256 = identity::source_hash(source);
    match profile {
        mori_core::LANGUAGE => {
            // `parse` validates before returning (parser.rs:157-159).
            let program = mori_core::parse(source).map_err(CompileError::Core)?;
            admit_checked(program, Some(source_sha256)).map(Admitted::Core1)
        }
        mori_core::stage::LANGUAGE_2 => {
            let staged = mori_core::stage::load(source).map_err(CompileError::Core)?;
            Ok(Admitted::Staged2(StagedAdmission::new(staged, source_sha256)))
        }
        other => Err(CompileError::Profile(other.to_string())),
    }
}

/// Admit an in-memory `/1` Program through the same Core checks.
pub fn admit_program(program: Program) -> Result<AdmittedCore1, CompileError> {
    admit_checked(program, None)
}

fn admit_checked(program: Program, source_sha256: Option<Digest32>) -> Result<AdmittedCore1, CompileError> {
    mori_core::stage::require_core1(&program).map_err(CompileError::Core)?;
    mori_core::validate(&program).map_err(CompileError::Core)?;
    let program_hash = identity::program_hash(&program)?;
    let identity = ProgramIdentity {
        language: program.language.clone(),
        semantics: program.semantics.clone(),
        program_hash,
        source_sha256,
    };
    Ok(AdmittedCore1 { program, identity })
}

pub fn require_core1(program: &Program) -> Result<(), Error> {
    if program.language != LANGUAGE || program.semantics != SEMANTICS {
        return Err(Error::new("profile", PROFILE_MESSAGE));
    }
    if program
        .actions
        .iter()
        .flat_map(|action| &action.statements)
        .any(|statement| matches!(statement, Statement::Await { .. }))
    {
        return Err(Error::new("profile", "Await requires moriarty-core/2."));
    }
    Ok(())
}

pub fn parse(source: &str) -> Result<Program, Error> {
    parse_profile(source, false)
}

/// Syntax-only parser; only stage::load admits the resulting source.
pub(crate) fn parse_v2(source: &str) -> Result<Program, Error> {
    parse_profile(source, true)
}

