fn ty(&mut self) -> Result<Type, Error> {
    match self.word()?.as_str() {
        "UInt" => Ok(Type::UInt),
        "Bool" => Ok(Type::Bool),
        _ => Err(self.error("type", "Supported types are UInt and Bool.")),
    }
}
fn literal(&mut self) -> Result<Value, Error> {
    if self.eat("true") {
        return Ok(Value::Bool(true));
    }
    if self.eat("false") {
        return Ok(Value::Bool(false));
    }
    if self.peek().kind != TokenKind::Number {
        return Err(self.error("syntax", "Expected an unsigned integer or boolean literal."));
    }
    let raw = self.peek().text.replace('_', "");
    let n = raw.parse::<u128>().map_err(|_| {
        self.error(
            "number",
            "UInt literal must fit u128; amounts use integral atomic units.",
        )
    })?;
    self.pos += 1;
    Ok(Value::UInt(UInt(n)))
}
fn push(&mut self, expr: Expr) -> Result<ExprId, Error> {
    if self.program.expressions.len() >= MAX_EXPRESSIONS {
        return Err(self.error("bound", "Program exceeds 8,192 expression nodes."));
    }
    let id = self.program.expressions.len() as u16;
    self.program.expressions.push(expr);
    Ok(id)

fn expr(&mut self, minimum: u8, depth: usize) -> Result<ExprId, Error> {
    if depth > 64 {
        return Err(self.error("bound", "Expression nesting exceeds 64."));
    }
    let mut lhs = if self.eat("(") {
        let e = self.expr(0, depth + 1)?;
        self.expect(")")?;
        e
    } else if self.eat("not") {
        let value = self.expr(6, depth + 1)?;
        self.push(Expr::Not { value })?
    } else if self.peek().kind == TokenKind::Number
        || self.peek().text == "true"
        || self.peek().text == "false"
    {
        let value = self.literal()?;
        self.push(Expr::Literal { value })?
    } else {
        let name = self.word()?;
        if matches!(name.as_str(), "liability_present" | "liability_amount") && self.eat("(") {
            let duty = self.string()?;
            self.expect(")")?;
            self.push(if name == "liability_present" {
                Expr::LiabilityPresent { name: duty }
            } else {
                Expr::LiabilityAmount { name: duty }
            })?
        } else {
            self.push(Expr::Name { name })?
        }
    };
    loop {
        // A decoded string spelling an operator is still a string token.
        if self.peek().kind == TokenKind::String {
            break;
        }
        let next = self
            .tokens
            .get(self.pos + 1)
            .filter(|t| t.kind != TokenKind::String)
            .map(|t| t.text.as_str());
        let (op, precedence, length) = match (self.peek().text.as_str(), next) {
            ("or", _) => (BinaryOp::Or, 1, 1),
            ("and", _) => (BinaryOp::And, 2, 1),
            ("=", Some("=")) => (BinaryOp::Eq, 3, 2),
            ("not", Some("=")) => (BinaryOp::Ne, 3, 2),
            ("<", Some("=")) => (BinaryOp::Le, 3, 2),
            (">", Some("=")) => (BinaryOp::Ge, 3, 2),
            ("<", _) => (BinaryOp::Lt, 3, 1),
            (">", _) => (BinaryOp::Gt, 3, 1),
            ("+", _) => (BinaryOp::Add, 4, 1),
            ("-", _) => (BinaryOp::Sub, 4, 1),
            ("*", _) => (BinaryOp::Mul, 5, 1),
            _ => break,

fn statement(&mut self) -> Result<Statement, Error> {
    let keyword = self.word()?;
    let s=match keyword.as_str() {
        "await" if self.program.language == crate::stage::LANGUAGE_2 => {
            let label = self.word()?;
            self.expect("(")?;
            let mut binders = Vec::new();
            if !self.eat(")") {
                loop {
                    let name = self.word()?;
                    self.expect(":")?;
                    let ty = self.ty()?;
                    binders.push(InputDecl { name, ty });
                    if self.eat(")") { break; }
                    self.expect(",")?;
                }
            }
            self.expect("when")?;
            Statement::Await { label, binders, guard: self.expr(0, 0)? }
        },
        "let"=>{let name=self.word()?;self.expect("=")?;Statement::Let{name,value:self.expr(0,0)?}},
        "next"=>{let state=self.word()?;self.expect("=")?;Statement::Next{state,value:self.expr(0,0)?}},
        "requires"=>Statement::Requires{predicate:self.expr(0,0)?},
        "ensures"=>Statement::Ensures{predicate:self.expr(0,0)?},
        "emit"=>{let name=self.string()?;self.expect("(")?;let value=self.expr(0,0)?;self.expect(")")?;Statement::Emit{name,value}},
        "transfer"|"fee"=>{self.expect("(")?;let asset=self.word()?;self.expect(",")?;let from=self.string()?;self.expect(",")?;let to=self.string()?;self.expect(",")?;let amount=self.expr(0,0)?;self.expect(")")?;if keyword=="fee"{Statement::Fee{asset,from,to,amount}}else{Statement::Transfer{asset,from,to,amount}}},
        "liability"=>{self.expect("(")?;let name=self.string()?;self.expect(",")?;let asset=self.word()?;self.expect(",")?;let debtor=self.string()?;self.expect(",")?;let creditor=self.string()?;self.expect(",")?;let amount=self.expr(0,0)?;self.expect(")")?;Statement::Liability{name,asset,debtor,creditor,amount}},
        "discharge"=>{self.expect("(")?;let name=self.string()?;self.expect(",")?;let amount=self.expr(0,0)?;self.expect(")")?;Statement::Discharge{name,amount}},
        _=>return Err(self.error("unsupported",format!("Unsupported statement {keyword:?}; use let, requires, ensures, next, emit, transfer, fee, liability or discharge."))),
    };
    self.expect(";")?;
    Ok(s)

pub fn validate(program: &Program) -> Result<(), Error> {
    if program.language != LANGUAGE || program.semantics != SEMANTICS {
        return Err(failure(
            "profile",
            "Unsupported language or semantics identity.",
        ));
    }
    if !identifier(&program.name) {
        return Err(failure(
            "name",
            "Agreement name must be a non-reserved ASCII identifier of at most 64 bytes.",
        ));
    }
    if program.actions.is_empty() {
        return Err(failure("program", "Program needs at least one action."));
    }
    if program.states.len() + program.assets.len() + program.actions.len() > MAX_DECLARATIONS
        || program.expressions.len() > MAX_EXPRESSIONS
    {
        return Err(failure(
            "bound",
            "Program exceeds finite declaration/expression bounds.",
        ));
    }
    names(
        program
            .states
            .iter()
            .map(|s| s.name.as_str())
            .chain(program.assets.iter().map(|a| a.name.as_str())),
        "declaration",
    )?;
    names(program.actions.iter().map(|a| a.name.as_str()), "action")?;

let mut identities = BTreeSet::new();
for asset in &program.assets {
    let id = &asset.identity;
    if id.network.is_empty()
        || id.issuer.is_empty()
        || id.reference.is_empty()
        || id.network.len() > 1024
        || id.issuer.len() > 1024
        || id.reference.len() > 1024
        || id.scale > 38
        || !identities.insert(id)
    {
        return Err(failure(
            "asset",
            "Asset identities must be complete, unique and use scale 0..38.",
        ));
    }
    if program.assets.iter().any(|other| {
        other.identity.network == id.network
            && other.identity.issuer == id.issuer
            && other.identity.reference == id.reference
            && other.identity.scale != id.scale
    }) {
        return Err(failure(
            "asset",
            "Same asset identity cannot have conflicting scales.",
        ));
    }
}

let mut depths = Vec::with_capacity(program.expressions.len());
for (i, e) in program.expressions.iter().enumerate() {
    let refs = match e {
        Expr::Binary { lhs, rhs, .. } => vec![*lhs, *rhs],
        Expr::Not { value } => vec![*value],
        _ => vec![],
    };
    let mut depth = 0;
    for r in refs {
        if usize::from(r) >= i {
            return Err(failure(
                "expression",
                "Expression references must point to earlier nodes; cycles are forbidden.",
            ));
        }
        depth = depth.max(depths[usize::from(r)] + 1);
    }
    if depth > 64 {
        return Err(failure("bound", "Expression depth exceeds 64."));
    }
    depths.push(depth);
}
let state_types: BTreeMap<_, _> = program
    .states
    .iter()
    .map(|s| (s.name.clone(), s.ty))
    .collect();
for state in &program.states {
    if state.initial.ty() != state.ty {
        return Err(failure(
            "type",
            format!("Initial state {:?} has wrong type.", state.name),
        ));
    }
}
for action in &program.actions {
    if action.inputs.len() > MAX_DECLARATIONS || action.statements.len() > MAX_STATEMENTS {
        return Err(failure(
            "bound",
            "Action exceeds input or statement bounds.",
        ));
    }
    names(action.inputs.iter().map(|i| i.name.as_str()), "input")?;
    let mut env = state_types.clone();
    for input in &action.inputs {
        if env.insert(input.name.clone(), input.ty).is_some()
            || program.assets.iter().any(|a| a.name == input.name)
        {
            return Err(failure("duplicate", "Input cannot shadow a declaration."));
        }
    }

    for statement in &action.statements {
        match statement {
            // Same identity as `stage::require_core1`; only an in-memory
            // program can carry Await here, since `/1` JSON cannot.
            Statement::Await { .. } => {
                return Err(failure("profile", "Await requires moriarty-core/2."));
            }
            Statement::Let { name, value } => {
                let ty = expr_type(program, *value, &env, 0)?;
                if !identifier(name)
                    || env.insert(name.clone(), ty).is_some()
                    || program.assets.iter().any(|a| a.name == *name)
                {
                    return Err(failure("duplicate", "let cannot shadow an existing name."));
                }
            }
            Statement::Requires { predicate } | Statement::Ensures { predicate } => {
                if expr_type(program, *predicate, &env, 0)? != Type::Bool {
                    return Err(failure("type", "Predicate must have type Bool."));
                }
            }
            Statement::Next { state, value } => {
                let expected = state_types
                    .get(state)
                    .ok_or_else(|| failure("name", format!("Unknown state {state:?}.")))?;
                if expr_type(program, *value, &env, 0)? != *expected {
                    return Err(failure("type", "State update has wrong type."));
                }
            }
            Statement::Emit { name, value } => {
                if name.is_empty() || name.len() > 1024 {
                    return Err(failure("name", "Event name must contain 1..1024 bytes."));
                }
                expr_type(program, *value, &env, 0)?;
            }
            Statement::Transfer {
                asset,
                from,
                to,
                amount,
            }
            | Statement::Fee {
                asset,
                from,
                to,
                amount,
            } => {
                validate_asset(program, asset)?;
                if from.is_empty() || to.is_empty() || from.len() > 1024 || to.len() > 1024 {
                    return Err(failure("account", "Account identities cannot be empty."));
                }
                require_uint(program, *amount, &env)?;
            }
            Statement::Liability {
                name,
                asset,
                debtor,
                creditor,
                amount,
            } => {
                validate_asset(program, asset)?;
                if name.is_empty()
                    || debtor.is_empty()
                    || creditor.is_empty()
                    || name.len() > 1024
                    || debtor.len() > 1024
                    || creditor.len() > 1024
                {
                    return Err(failure(
                        "liability",
                        "Liability identities cannot be empty.",
                    ));
                }
                require_uint(program, *amount, &env)?;
            }
            Statement::Discharge { name, amount } => {
                if name.is_empty() || name.len() > 1024 {
                    return Err(failure(
                        "liability",
                        "Liability name must contain 1..1024 bytes.",
                    ));
                }
                require_uint(program, *amount, &env)?;
            }
        }
    }
}

    validate_liability_reads(program)?;
    Ok(())
}
// New reads require a source-fixed identity. Legacy Core external duties and
// discharge-only programs keep their existing validation rules.
pub(crate) fn validate_liability_reads(p: &Program) -> Result<(), Error> {
    let mut reads = BTreeMap::new();
    for expr in &p.expressions {
        if let Expr::LiabilityPresent { name } | Expr::LiabilityAmount { name } = expr {
            if name.is_empty() || name.len() > 1024 {
                return Err(failure(
                    "liability",
                    "Liability read name must contain 1..1024 bytes.",
                ));
            }
            reads.insert(name.as_str(), None);
        }
    }
    for stmt in p.actions.iter().flat_map(|a| &a.statements) {
        if let Statement::Liability {
            name,
            asset,
            debtor,
            creditor,
            ..
        } = stmt
        {
            if let Some(found) = reads.get_mut(name.as_str()) {
                let identity = (
                    validate_asset(p, asset)?,
                    debtor.as_str(),
                    creditor.as_str(),
                );
                if found.is_some_and(|previous| previous != identity) {
                    return Err(failure(
                        "liability",
                        format!("Conflicting source liability identity for {name:?}."),
                    ));
                }
                *found = Some(identity);
            }
        }
    }
    for (name, identity) in reads {
        if identity.is_none() {
            return Err(failure(
                "liability",
                format!("Liability read {name:?} has no source-derived identity."),
            ));
        }
    }
    Ok(())
}

/// Legacy identifier rule with `await` and `when` also reserved (C6).
fn identifier_v2(name: &str) -> bool {
    identifier(name) && !matches!(name, "await" | "when")
}

fn names_v2<'a>(values: impl Iterator<Item = &'a str>, kind: &str) -> Result<(), Error> {
    let mut seen = BTreeSet::new();
    for name in values {
        if !identifier_v2(name) || !seen.insert(name) {
            return Err(failure(
                "duplicate",
                format!("Invalid or duplicate {kind} name {name:?}."),
            ));
        }
    }
    Ok(())

for action in &program.actions {
    if action.inputs.len() > MAX_DECLARATIONS || action.statements.len() > MAX_STATEMENTS {
        return Err(failure(
            "bound",
            "Action exceeds input or statement bounds.",
        ));
    }
    names_v2(action.inputs.iter().map(|i| i.name.as_str()), "input")?;
    let mut env = state_types.clone();
    for input in &action.inputs {
        if env.insert(input.name.clone(), input.ty).is_some()
            || program.assets.iter().any(|a| a.name == input.name)
        {
            return Err(failure("duplicate", "Input cannot shadow a declaration."));
        }
    }
    let mut labels = BTreeSet::new();
    let mut awaits = 0_usize;
    // Inputs, lets and earlier binders: the captures of the next site.
    let mut captured = action.inputs.len();
    for statement in &action.statements {
        match statement {
            Statement::Await {
                label,
                binders,
                guard,
            } => {
                awaits += 1;
                if awaits > MAX_AWAITS_PER_ACTION {
                    return Err(failure("bound", "Action exceeds 16 awaits."));
                }
                if binders.len() > MAX_EVENT_BINDERS {
                    return Err(failure("bound", "Await exceeds 16 event binders."));
                }
                if captured > MAX_CAPTURE_SLOTS {
                    return Err(failure("bound", "Await site exceeds 256 capture slots."));
                }
                if !identifier_v2(label) || !labels.insert(label.as_str()) {
                    return Err(failure(
                        "duplicate",
                        format!("Invalid or duplicate await label {label:?}."),
                    ));
                }
                for binder in binders {
                    if !identifier_v2(&binder.name)
                        || env.insert(binder.name.clone(), binder.ty).is_some()
                        || program.assets.iter().any(|a| a.name == binder.name)
                    {
                        return Err(failure(
                            "duplicate",
                            "Await binder cannot shadow an existing name.",
                        ));
                    }
                }
                if expr_type(program, *guard, &env, 0)? != Type::Bool {
                    return Err(failure("type", "Await guard must have type Bool."));
                }
                captured += binders.len();
            }
            Statement::Let { name, value } => {
                let ty = expr_type(program, *value, &env, 0)?;
                if !identifier_v2(name)
                    || env.insert(name.clone(), ty).is_some()
                    || program.assets.iter().any(|a| a.name == *name)
                {
                    return Err(failure("duplicate", "let cannot shadow an existing name."));
                }
                captured += 1;

/// Builds layouts after validate_v2. Costs and hashes are filled by stage::load.
pub(crate) fn build(program: &Program) -> Result<StagePlan, Error> {
    let mut actions = Vec::new();
    for action in &program.actions {
        let mut types: BTreeMap<_, _> = program.states.iter()
            .map(|state| (state.name.clone(), state.ty)).collect();
        let mut captures = Vec::new();
        for (ordinal, input) in action.inputs.iter().enumerate() {
            types.insert(input.name.clone(), input.ty);
            captures.push(CaptureSlot {
                name: input.name.clone(), ty: input.ty,
                origin: Origin::Input, ordinal: ordinal as u16,
            });
        }
        let mut sites = Vec::new();
        for (ordinal, statement) in action.statements.iter().enumerate() {
            match statement {
                Statement::Let { name, value } => {
                    let ty = crate::runtime::expr_type(program, *value, &types, 0)?;
                    types.insert(name.clone(), ty);
                    captures.push(CaptureSlot {
                        name: name.clone(), ty, origin: Origin::Let, ordinal: ordinal as u16,
                    });
                }
                Statement::Await { label, binders, .. } => {
                    sites.push(AwaitSite {
                        site: sites.len() as u16 + 1,
                        ordinal: ordinal as u16,
                        label: label.clone(),
                        binders: binders.iter().map(StageBinder::from).collect(),
                        captures: captures.clone(),
                    });
                    for binder in binders {
                        types.insert(binder.name.clone(), binder.ty);
                        captures.push(CaptureSlot {
                            name: binder.name.clone(), ty: binder.ty,
                            origin: Origin::Event, ordinal: ordinal as u16,
                        });
                    }
                }
                _ => {}
            }
        }
        actions.push(ActionPlan {
            action: action.name.clone(), statement_count: action.statements.len() as u16,
            sites, segment_cost: Vec::new(), committed_before: Vec::new(), plan_total: UInt(0),
        });
    }
    Ok(StagePlan {
        format: "moriarty-stage-plan/1".into(), program_hash: String::new(), actions,
    })
}

/// Independently re-derives each action's sites and capture layouts and
/// requires the Sol-built plan to equal them, then checks the A3 predicates
/// explicitly. Runs before costing, so cost vectors and hash must be empty.
pub(crate) fn plan_invariants(program: &Program, plan: &StagePlan) -> Result<(), Error> {
    if plan.format != STAGE_PLAN_FORMAT {
        return Err(invariant("format"));
    }
    if !plan.program_hash.is_empty() {
        return Err(invariant("program hash filled before costing"));
    }
    if plan.actions.len() != program.actions.len() {
        return Err(invariant("action count"));
    }
    let state_names: BTreeSet<_> = program.states.iter().map(|s| s.name.as_str()).collect();
    for (action, ap) in program.actions.iter().zip(&plan.actions) {
        if ap.action != action.name || usize::from(ap.statement_count) != action.statements.len()
        {
            return Err(invariant("action identity"));
        }
        if !ap.segment_cost.is_empty() || !ap.committed_before.is_empty() || ap.plan_total != UInt(0)
        {
            return Err(invariant("costs filled before costing"));
        }

        Statement::Await { label, binders, .. } => {
            expected.push(AwaitSite {
                site: u16::try_from(expected.len() + 1).map_err(|_| invariant("site"))?,
                ordinal,
                label: label.clone(),
                binders: binders.iter().map(StageBinder::from).collect(),
                captures: slots.clone(),
            });
            for binder in binders {
                types.insert(binder.name.clone(), binder.ty);
                slots.push(CaptureSlot {
                    name: binder.name.clone(),
                    ty: binder.ty,
                    origin: Origin::Event,
                    ordinal,
                });
            }
        }
        _ => {}
    }
}
if ap.sites != expected {
    return Err(invariant("sites differ from source"));
}
// Explicit A3 predicates, stated separately from the derivation.
if ap.sites.len() > MAX_AWAITS_PER_ACTION {
    return Err(failure("bound", "Action exceeds 16 awaits."));
}
let mut previous: Option<&AwaitSite> = None;
for (index, site) in ap.sites.iter().enumerate() {
    if usize::from(site.site) != index + 1 {
        return Err(invariant("sites are not numbered 1..N"));
    }
    if previous.is_some_and(|p| p.ordinal >= site.ordinal) {
        return Err(invariant("ordinals are not strictly increasing"));
    }
    if site.binders.len() > MAX_EVENT_BINDERS || site.captures.len() > MAX_CAPTURE_SLOTS {
        return Err(failure("bound", "Await site exceeds stage layout bounds."));
    }
    let inputs = action.inputs.len();
    if site.captures.len() < inputs
        || site.captures[..inputs]
            .iter()
            .zip(&action.inputs)
            .enumerate()
            .any(|(i, (slot, input))| {
                slot.origin != Origin::Input
                    || slot.name != input.name
                    || slot.ty != input.ty
                    || usize::from(slot.ordinal) != i
            })
    {
        return Err(invariant("captures do not begin with all inputs"));
    }
    let mut seen = BTreeSet::new();
    for slot in &site.captures {
        if state_names.contains(slot.name.as_str())
            || !seen.insert(slot.name.as_str())
            || (slot.origin != Origin::Input && slot.ordinal >= site.ordinal)
        {
            return Err(invariant("capture names a state, repeats or follows its site"));
        }
    }
    if let Some(p) = previous {
        if !site.captures.starts_with(&p.captures) {
            return Err(invariant("captures are not prefix-monotone"));
        }
    }
    previous = Some(site);

/// Strict JSON decoding of `bytes` into `T`.
pub fn parse_json<T: DeserializeOwned>(bytes: &[u8], what: &str) -> Result<T, DriverError> {
    if bytes.len() > MAX_JSON_BYTES {
        return Err(DriverError::Input(format!("{what}: {} bytes exceed the JSON bound", bytes.len())));
    }
    let text = std::str::from_utf8(bytes).map_err(|_| DriverError::Input(format!("{what}: not UTF-8")))?;
    let value = mori_core::json::parse_limited(text, MAX_JSON_BYTES, "JSON input exceeds the driver bound")
        .map_err(|e| DriverError::Input(format!("{what}: {e}")))?;
    serde_json::from_value(value).map_err(|e| DriverError::Input(format!("{what}: {e}")))
}

fn deserialize<D: serde::Deserializer<'de>>(self, d: D) -> Result<Value, D::Error> {
    use serde::de::Error as _;
    self.nodes.set(self.nodes.get() + 1);
    if self.depth > 32 || self.nodes.get() > 65_536 {
        return Err(D::Error::custom("JSON work/depth limit"));
    }
    d.deserialize_any(self)

fn visit_seq<A: SeqAccess<'de>>(self, mut a: A) -> Result<Value, A::Error> {
    let mut out = Vec::new();
    while let Some(v) = a.next_element_seed(Seed {
        depth: self.depth + 1,
        nodes: self.nodes,
    })? {
        out.push(v)
    }
    Ok(Value::Array(out))
}
fn visit_map<A: MapAccess<'de>>(self, mut a: A) -> Result<Value, A::Error> {
    use serde::de::Error as _;
    let mut out = Map::new();
    while let Some(k) = a.next_key::<String>()? {
        if out.contains_key(&k) {
            return Err(A::Error::custom("duplicate decoded key"));
        }
        let v = a.next_value_seed(Seed {
            depth: self.depth + 1,
            nodes: self.nodes,
        })?;
        out.insert(k, v);
    }
    Ok(Value::Object(out))
}

pub fn parse(text: &str) -> Result<Value, Error> {
    parse_inner(text, MAX_BYTES, "JSON exceeds 1 MiB")
}
/// The same strict parser under a caller-selected byte ceiling. Duplicate-key,
/// depth (32) and node (65,536) limits are unchanged; `/2` stage files use it.
pub fn parse_limited(text: &str, max: usize, too_large: &'static str) -> Result<Value, Error> {
    parse_inner(text, max, too_large)
}
fn parse_inner(text: &str, max: usize, too_large: &'static str) -> Result<Value, Error> {
    use serde::de::DeserializeSeed;
    if text.len() > max {
        return Err(Error::new("json", too_large));
    }
    let nodes = Cell::new(0);
    let mut decoder = serde_json::Deserializer::from_str(text);
    let value = Seed {
        depth: 0,
        nodes: &nodes,
    }
    .deserialize(&mut decoder)
    .map_err(|e| Error::new("json", e.to_string()))?;
    decoder
        .end()
        .map_err(|e| Error::new("json", e.to_string()))?;
    Ok(value)

/// Which relation to compile. Every option is spelled out; the driver supports exactly one
/// value of each and refuses the rest (see [`crate::relation::check_selector`]).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct RelationSelector {
    pub format: String,
    pub language: String,
    pub semantics: String,
    pub action: String,
    pub adapter: String,
    pub cap: String,
    pub accounting: String,
    pub frame: String,
    /// Optional pin: lowercase hex SHA-256 of the raw source bytes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_source_sha256: Option<String>,
    /// Optional pin: lowercase hex canonical typed-Program hash.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_program_hash: Option<String>,
}

/// The claimed transition, as a proposal. There is no default kind.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
pub enum TransitionInput {
    /// Core `simulate` proposes the transition for this scenario.
    CoreReference { scenario: Scenario },
    /// Explicit typed records: inputs, pre and post snapshots and ordered effects.
    Records { inputs: BTreeMap<String, Value>, pre: Snapshot, post: Snapshot, effects: Vec<Effect> },
}

/// Per-proof context bytes, as caller-declared premises. The VK digest is derived from the
/// VK actually used; if a request restates it, the two must be equal.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ContextInput {
    pub claimant_vkh: String,
    pub network_id: u8,
    pub settle_hash: String,
    pub thread_id: String,
    pub consumed_txid: String,
    pub consumed_ix: u16,
    pub seq: u64,
    pub catalogue_digest: String,
    pub intents_digest: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vk_digest: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ProveRequest {
    pub format: String,
    pub selector: RelationSelector,
    pub transition: TransitionInput,
    pub context: ContextInput,
}

/// Source text ceiling (bytes).
pub const MAX_SOURCE_BYTES: u64 = 262_144;
/// JSON document ceiling; equal to Core's own `json::parse` ceiling.
pub const MAX_JSON_BYTES: usize = 1_048_576;
/// Proving-key file ceiling. The real size is unmeasured; a larger key is refused, not read.
pub const MAX_PROVING_KEY_BYTES: u64 = 2 * 1024 * 1024 * 1024;

/// Reads a regular file of at most `max` bytes. Devices, directories and larger files are
/// refused before their content is read.
pub fn read_bounded(path: &Path, max: u64, what: &str) -> Result<Vec<u8>, DriverError> {
    let file = File::open(path).map_err(|e| DriverError::Io(format!("{what}: cannot open {}: {e}", path.display())))?;
    let meta = file.metadata().map_err(|e| DriverError::Io(format!("{what}: cannot stat {}: {e}", path.display())))?;
    if !meta.is_file() {
        return Err(DriverError::Io(format!("{what}: {} is not a regular file", path.display())));
    }
    if meta.len() > max {
        return Err(DriverError::Input(format!("{what}: {} bytes exceed the {max}-byte bound", meta.len())));
    }
    let mut out = Vec::new();
    file.take(max.saturating_add(1))
        .read_to_end(&mut out)
        .map_err(|e| DriverError::Io(format!("{what}: cannot read {}: {e}", path.display())))?;
    if out.len() as u64 > max {
        return Err(DriverError::Input(format!("{what}: file grew beyond the {max}-byte bound while read")));
    }
    Ok(out)
}

/// Reads a source file as UTF-8 text.
pub fn read_source(path: &Path) -> Result<String, DriverError> {
    let bytes = read_bounded(path, MAX_SOURCE_BYTES, "source")?;
    String::from_utf8(bytes).map_err(|_| DriverError::Input("source: not UTF-8".into()))

pub const LANGUAGE: &str = "moriarty/1";
pub const SEMANTICS: &str = "moriarty-core/1";
pub const CAP: &str = "NotBound";
pub const ACCOUNTING: &str = "GrossDebitAndFees";
pub const FRAME: &str = "TouchedOnly";
/// SettlementHashV2 public inputs: the two 128-bit digest halves.
pub const PUBLIC_INPUTS: u8 = 2;
/// arkworks counts the constant-one instance variable: 1 + 2.
pub const INSTANCE_VARIABLES: u64 = 3;

/// Refuses every selector value outside the one supported profile. Runs before compilation.
pub fn check_selector(s: &RelationSelector) -> Result<(), DriverError> {
    let fixed = [
        ("format", s.format.as_str(), SELECTOR_FORMAT),
        ("language", s.language.as_str(), LANGUAGE),
        ("semantics", s.semantics.as_str(), SEMANTICS),
        ("adapter", s.adapter.as_str(), crate::ADAPTER),
        ("cap", s.cap.as_str(), CAP),
        ("accounting", s.accounting.as_str(), ACCOUNTING),
        ("frame", s.frame.as_str(), FRAME),
    ];
    for (what, got, want) in fixed {
        if got != want {
            return Err(DriverError::Unsupported(format!("selector {what} {got:?}; this driver supports only {want:?}")));
        }
    }
    if s.action.is_empty() || s.action.len() > 1024 {
        return Err(DriverError::Input("selector action must contain 1..1024 bytes".into()));
    }
    Ok(())

/// Compiles `source` for `selector` with the actual compiler, then checks optional pins.
pub fn compile_selected(source: &str, selector: &RelationSelector) -> Result<SelectedRelation, DriverError> {
    check_selector(selector)?;
    let options = CompileOptions {
        action: selector.action.clone(),
        cap: CapBinding::NotBound,
        frame: FrameCells::TouchedOnly,
        accounting: AccountingBinding::GrossDebitAndFees,
        compiler: CompilerBuild::embedded().map_err(DriverError::Compile)?,
    };
    let relation =
        mori_r1cs::compile_source::<Fr>(source, options, StatementAdapter::SettlementHashV2).map_err(DriverError::Compile)?;
    let descriptor = RelationDescriptor::of(&relation)?;

/// Compiles `source` for `selector` with the actual compiler, then checks optional pins.
pub fn compile_selected(source: &str, selector: &RelationSelector) -> Result<SelectedRelation, DriverError> {
    check_selector(selector)?;
    let options = CompileOptions {
        action: selector.action.clone(),
        cap: CapBinding::NotBound,
        frame: FrameCells::TouchedOnly,
        accounting: AccountingBinding::GrossDebitAndFees,
        compiler: CompilerBuild::embedded().map_err(DriverError::Compile)?,
    };
    let relation =
        mori_r1cs::compile_source::<Fr>(source, options, StatementAdapter::SettlementHashV2).map_err(DriverError::Compile)?;
    let descriptor = RelationDescriptor::of(&relation)?;
    if descriptor.language != selector.language || descriptor.semantics != selector.semantics {
        return Err(DriverError::mismatch(
            "language/semantics",
            format!("{}/{}", selector.language, selector.semantics),
            format!("{}/{}", descriptor.language, descriptor.semantics),
        ));
    }
    if let Some(pin) = &selector.expected_source_sha256 {
        hexutil::decode_exact::<32>(pin, "expectedSourceSha256")?;
        let actual = descriptor.source_sha256.clone().unwrap_or_default();
        if *pin != actual {
            return Err(DriverError::mismatch("source sha256", pin.clone(), actual));
        }
    }
    if let Some(pin) = &selector.expected_program_hash {
        hexutil::decode_exact::<32>(pin, "expectedProgramHash")?;
        if *pin != descriptor.program_hash {
            return Err(DriverError::mismatch("program hash", pin.clone(), descriptor.program_hash.clone()));
        }
    }
    Ok(SelectedRelation { selector: selector.clone(), relation, descriptor })

/// Routes source by its declared profile and compiles `/1`. `/2` is admitted by the
/// actual stage loader and then refused with its staged lowering plan.
pub fn compile_source<F: PrimeField>(source: &str, options: CompileOptions, adapter: StatementAdapter) -> Result<CompiledRelation, CompileError> {
    match frontend::admit_source(source)? {
        Admitted::Core1(admitted) => compile::<F>(admitted, options, adapter),
        Admitted::Staged2(staged) => Err(CompileError::StagedNotLowered(Box::new(staged.lowering_plan()?))),
    }
}

/// Compiles one action of an admitted `/1` Program over the scalar field `F`.
pub fn compile<F: PrimeField>(admitted: AdmittedCore1, options: CompileOptions, adapter: StatementAdapter) -> Result<CompiledRelation, CompileError> {
    if F::MODULUS_BIT_SIZE < crate::MIN_MODULUS_BITS {
        return Err(CompileError::Field(format!(
            "scalar field has {} bits; the exact-integer gadgets need at least {}",
            F::MODULUS_BIT_SIZE,
            crate::MIN_MODULUS_BITS
        )));
    }
    let build = options.compiler.checked()?;
    adapter.admits(admitted.program()).map_err(CompileError::Adapter)?;
    if adapter == StatementAdapter::SettlementHashV2 {
        abi2::options_ok(&options)?;
    }
    let plan = plan::plan_action(admitted.program(), &options)?;
    let layout = StatementLayout::build(admitted.identity(), &plan, build)?;

let abi2 = if adapter == StatementAdapter::SettlementHashV2 {
    Some(abi2::constants(admitted.program(), &plan, &layout, identity.digest()?.0)?)
} else {
    None
};
let mut relation = CompiledRelation { admitted, options, plan, layout, identity, adapter, abi2, probe: placeholder };
relation.probe = probe::<F>(&relation)?;
Ok(relation)

/// How the logical-work cap appears in the statement. No default exists: the caller
/// chooses explicitly. This does not select the split D-13 stored-cap convention for
/// `/2`; it only says whether a `/1` claim carries a cap at all.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum CapBinding {
    /// Statement has no cap slot; the relation matches unmetered `simulate`.
    NotBound,
    /// Statement carries a UInt cap and the circuit enforces `W <= cap`, matching
    /// `simulate_metered(cap)`.
    PublicCap,
}

/// Whether the statement carries an in-circuit accounting summary. No default: the
/// caller chooses. UNADOPTED: this implements the gross-debit and fee part of the
/// one-vote P3-3(d) proposal (claim-utxo-abi-v1 VOTES.md §4) and needs a second vote.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum AccountingBinding {
    NotBound,
    /// For every represented cell named as `from` by a Transfer or Fee, two public
    /// 144-bit sums: gross debit (Transfer and Fee amounts, self-transfers included,
    /// as `intent::check_effects` counts them) and fees paid (Fee amounts).
    GrossDebitAndFees,
}

/// A balance cell named by source asset name and account.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct CellRef {
    pub asset: String,
    pub account: String,
}

/// Which balance cells the statement represents beyond those the action touches.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum FrameCells {
    /// Only cells named by the action's Transfer/Fee statements.
    TouchedOnly,
    /// Touched cells plus these extra preserved cells (for example a target layout's
    /// framed matrix). Extra cells are constrained `post == pre`.
    Include(Vec<CellRef>),
}

/// Every compile choice is explicit; there is no `Default`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CompileOptions {
    pub action: String,
    pub cap: CapBinding,
    pub frame: FrameCells,
    pub accounting: AccountingBinding,
    pub compiler: CompilerBuild,
}

/// Builds the plan for `options.action`.
pub fn plan_action(program: &Program, options: &CompileOptions) -> Result<ActionPlan, CompileError> {
    let action_index = program
        .actions
        .iter()
        .position(|a| a.name == options.action)
        .ok_or_else(|| CompileError::UnknownAction(options.action.clone()))?;
    let action = &program.actions[action_index];
    let action_index = u16::try_from(action_index).map_err(|_| CompileError::Bound("action index exceeds u16".into()))?;
    let statement_count =
        u16::try_from(action.statements.len()).map_err(|_| CompileError::Bound("statement count exceeds u16".into()))?;

    let inputs: Vec<NamedType> = action.inputs.iter().map(|i| NamedType { name: i.name.clone(), ty: i.ty }).collect();
    let mut states: Vec<NamedType> = program.states.iter().map(|s| NamedType { name: s.name.clone(), ty: s.ty }).collect();
    states.sort_by(|a, b| a.name.cmp(&b.name));

    let registry = registry(program)?;

    // Cells: touched by this action, then optional preserved frame cells.
    let mut cells: BTreeMap<(AssetId, String), (String, bool)> = BTreeMap::new();
    let mut liability_statements = 0usize;
    let mut touched_duties: BTreeSet<String> = BTreeSet::new();
    for statement in &action.statements {
        match statement {
            Statement::Transfer { asset, from, to, .. } | Statement::Fee { asset, from, to, .. } => {
                let id = asset_by_name(program, asset)?.clone();
                cells.insert((id.clone(), from.clone()), (asset.clone(), true));
                cells.insert((id, to.clone()), (asset.clone(), true));
            }
            Statement::Liability { name, .. } => {
                liability_statements += 1;
                touched_duties.insert(name.clone());
            }
            Statement::Discharge { name, .. } => {
                touched_duties.insert(name.clone());
            }
            Statement::Await { .. } => {
                return Err(CompileError::Unsupported {
                    construct: "Statement::Await",
                    reason: "Await is moriarty-core/2 only; /1 admission refuses it".into(),
                });
            }
            Statement::Let { .. }
            | Statement::Requires { .. }
            | Statement::Ensures { .. }
            | Statement::Next { .. }
            | Statement::Emit { .. } => {}
        }
        for id in reachable(program, statement_root(statement))? {
            if let Expr::LiabilityPresent { name } | Expr::LiabilityAmount { name } = &program.expressions[usize::from(id)] {
                touched_duties.insert(name.clone());
            }
        }
    }

if let FrameCells::Include(extra) = &options.frame {
    for cell in extra {
        if cell.account.is_empty() || cell.account.len() > 1024 {
            return Err(CompileError::Option("frame cell account must contain 1..1024 bytes".into()));
        }
        let id = asset_by_name(program, &cell.asset)?.clone();
        cells.entry((id, cell.account.clone())).or_insert((cell.asset.clone(), false));
    }
}
let cells: Vec<CellKey> = cells
    .into_iter()
    .map(|((asset, account), (asset_name, touched))| CellKey { asset_name, asset, account, touched })
    .collect();

// Duties: the whole source registry. A duty this action touches or reads without
// a source introduction would need a dynamic identity cell: refused (first slice).
for name in &touched_duties {
    if !registry.by_name.contains_key(name) {
        return Err(CompileError::Unsupported {
            construct: "external duty",
            reason: format!(
                "duty {name:?} has no source Liability introduction; its identity would be prover data. \
                 First slice represents only source-fixed duty identities."
            ),
        });
    }
}
let duties: Vec<DutyKey> = registry
    .by_name
    .iter()
    .map(|(name, (asset_name, asset, debtor, creditor))| DutyKey {
        name: name.clone(),
        asset_name: asset_name.clone(),
        asset: asset.clone(),
        debtor: debtor.clone(),
        creditor: creditor.clone(),
        touched: touched_duties.contains(name),
    })
    .collect();

    // Effect shapes and logical schedule, statement by statement.
    let mut env: BTreeMap<String, Type> = program.states.iter().map(|s| (s.name.clone(), s.ty)).collect();
    for input in &action.inputs {
        env.insert(input.name.clone(), input.ty);
    }
    let cell_at = |asset: &AssetId, account: &str| -> Result<usize, CompileError> {
        cells
            .iter()
            .position(|c| &c.asset == asset && c.account == account)
            .ok_or_else(|| CompileError::Bound("touched cell missing from plan".into()))
    };
    let duty_at = |name: &str| -> Result<usize, CompileError> {
        duties.iter().position(|d| d.name == name).ok_or_else(|| CompileError::Bound("duty missing from plan".into()))
    };
    let mut effects = Vec::new();
    let mut schedule = Vec::with_capacity(action.statements.len());
    let mut total: u128 = 0;
    for (index, statement) in action.statements.iter().enumerate() {
        let ordinal = index as u16;
        let cost = statement_cost(program, statement)?;
        total = total.checked_add(cost).ok_or_else(|| CompileError::Bound("logical work exceeds u128".into()))?;
        schedule.push(UInt(cost));
        match statement {
            Statement::Let { name, value } => {
                let ty = infer(program, *value, &env)?;
                env.insert(name.clone(), ty);
            }
            Statement::Next { state, .. } => {
                let ty = *env.get(state).ok_or_else(|| CompileError::Bound(format!("unknown state {state:?}")))?;
                effects.push(EffectShape::State { statement: ordinal, name: state.clone(), ty });
            }
            Statement::Emit { name, value } => {
                let ty = infer(program, *value, &env)?;
                effects.push(EffectShape::Emit { statement: ordinal, name: name.clone(), ty });
            }
            Statement::Transfer { asset, from, to, .. } | Statement::Fee { asset, from, to, .. } => {
                let id = asset_by_name(program, asset)?.clone();
                let from_cell = cell_at(&id, from)?;
                let to_cell = cell_at(&id, to)?;
                effects.push(if matches!(statement, Statement::Fee { .. }) {
                    EffectShape::Fee { statement: ordinal, asset: id, from: from.clone(), to: to.clone(), from_cell, to_cell }
                } else {
                    EffectShape::Transfer { statement: ordinal, asset: id, from: from.clone(), to: to.clone(), from_cell, to_cell }
                });
            }
            Statement::Liability { name, .. } => {
                effects.push(EffectShape::Liability { statement: ordinal, duty: duty_at(name)?, name: name.clone(), origin: DutyOrigin::Accrue });
            }
            Statement::Discharge { name, .. } => {
                effects.push(EffectShape::Liability { statement: ordinal, duty: duty_at(name)?, name: name.clone(), origin: DutyOrigin::Discharge });
            }
            Statement::Requires { .. } | Statement::Ensures { .. } => {}
            Statement::Await { .. } => unreachable!("refused above"),
        }
    }
    let debit_cells: Vec<usize> =
        effects.iter().filter_map(EffectShape::debit_cell).collect::<BTreeSet<_>>().into_iter().collect();

    // Core refuses scenarios whose trace product exceeds MAX_TRACE_CELLS
    // (runtime.rs:540-547). Counting every represented duty as present is the
    // conservative bound used by the Cardano layout as well (layout.rs:47-57). Rows
    // outside the represented snapshot are a target premise (see adapter.rs).
    let records = program.states.len() + cells.len() + duties.len() + liability_statements + 1;
    let trace = records
        .checked_mul(action.statements.len() + 2)
        .ok_or_else(|| CompileError::Bound("trace product overflow".into()))?;
    if trace > MAX_TRACE_CELLS {
        return Err(CompileError::Bound(format!(
            "represented snapshot needs {trace} trace records, above Core's {MAX_TRACE_CELLS}"
        )));
    }
    if cells.len() > 4096 || duties.len() > 1024 {
        return Err(CompileError::Bound("represented cells exceed Core's 4,096 balances or 1,024 liabilities".into()));
    }

    Ok(ActionPlan {
        action: action.name.clone(),
        action_index,
        statement_count,
        inputs,
        states,
        cells,
        duties,
        effects,
        debit_cells,
        logical_schedule: schedule,
        logical_work: UInt(total),
        cap: options.cap,
        accounting: options.accounting,
        frame: options.frame.clone(),
        represented_trace_cells: trace as u64,
    })
}

pub fn simulate(program: &Program, action: &str, scenario: &Scenario) -> Result<Execution, Error> {
    simulate_with_meter(program, action, scenario, None)
}
pub(crate) fn simulate_with_meter(
    program: &Program,
    action: &str,
    scenario: &Scenario,
    mut meter: Option<&mut Meter>,
) -> Result<Execution, Error> {
    validate(program)?;
    let selected = program
        .actions
        .iter()
        .find(|a| a.name == action)
        .ok_or_else(|| failure("action", format!("Unknown action {action:?}.")))?;
    let pre = scenario_snapshot(program, selected, scenario)?;
    let mut current = pre.clone();
    let mut env = current.state.clone();
    env.extend(scenario.inputs.clone());
    let mut steps = vec![];
    let mut all_effects = vec![];
    for (i, stmt) in selected.statements.iter().enumerate() {
        let mut effects = vec![];
        let result = execute_statement(
            program, stmt, &mut env, &mut current, &mut meter, &mut effects,
        );
        let value = result.map_err(|mut e| {
            e.step = Some(i as u16);
            e
        })?;
        all_effects.extend(effects.clone());
        steps.push(Step {
            index: i as u16,
            statement: stmt.clone(),
            value,
            snapshot: current.clone(),
            effects,
        });
    }
    Ok(Execution {
        semantics: SEMANTICS.into(),
        action: action.into(),
        pre,
        post: current,
        steps,
        effects: all_effects,
    })
}

fn evaluate(
    p: &Program,
    id: ExprId,
    env: &BTreeMap<String, Value>,
    snapshot: &Snapshot,
    meter: &mut Option<&mut Meter>,
) -> Result<Value, Error> {
    eval_cached(
        p,
        id,
        env,
        snapshot,
        &mut vec![None; p.expressions.len()],
        meter,
    )
}

fn eval_cached(
    p: &Program,
    id: ExprId,
    env: &BTreeMap<String, Value>,
    snapshot: &Snapshot,
    cache: &mut [Option<Value>],
    meter: &mut Option<&mut Meter>,
) -> Result<Value, Error> {
    let i = usize::from(id);
    if let Some(value) = &cache[i] {
        return Ok(value.clone());
    }
    // Charge the attempted node before its children or operation. Cache hits
    // above remain free, and evaluate creates a new cache for each statement.
    charge_logical(meter)?;
    let result = match &p.expressions[i] {
        Expr::LiabilityPresent { name } | Expr::LiabilityAmount { name } => {
            let row = snapshot
                .liabilities
                .binary_search_by(|l| l.name.as_str().cmp(name.as_str()))
                .ok()
                .map(|index| &snapshot.liabilities[index]);
            if matches!(&p.expressions[i], Expr::LiabilityPresent { .. }) {
                Value::Bool(row.is_some())
            } else {
                Value::UInt(row.map_or(UInt(0), |l| l.amount))
            }
        }
        Expr::Literal { value } => value.clone(),
        Expr::Name { name } => env
            .get(name)
            .cloned()
            .ok_or_else(|| failure("name", format!("Unknown name {name:?}.")))?,
        Expr::Not { value } => match eval_cached(p, *value, env, snapshot, cache, meter)? {
            Value::Bool(b) => Value::Bool(!b),
            _ => return Err(failure("type", "not expects Bool.")),
        },
        Expr::Binary { op, lhs, rhs } => {
            let a = eval_cached(p, *lhs, env, snapshot, cache, meter)?;
            let b = eval_cached(p, *rhs, env, snapshot, cache, meter)?;
            match (op, a, b) {
                (BinaryOp::Add, Value::UInt(UInt(a)), Value::UInt(UInt(b))) => {
                    Value::UInt(UInt(a.checked_add(b).ok_or_else(|| {
                        failure("overflow", "UInt addition exceeds u128.")
                    })?))
                }
                (BinaryOp::Sub, Value::UInt(UInt(a)), Value::UInt(UInt(b))) => {
                    Value::UInt(UInt(a.checked_sub(b).ok_or_else(|| {
                        failure("underflow", "UInt subtraction is negative.")
                    })?))
                }
                (BinaryOp::Mul, Value::UInt(UInt(a)), Value::UInt(UInt(b))) => {
                    Value::UInt(UInt(a.checked_mul(b).ok_or_else(|| {
                        failure("overflow", "UInt multiplication exceeds u128.")
                    })?))
                }
                (BinaryOp::Eq, a, b) => Value::Bool(a == b),
                (BinaryOp::Ne, a, b) => Value::Bool(a != b),
                (BinaryOp::Lt, Value::UInt(a), Value::UInt(b)) => Value::Bool(a < b),
                (BinaryOp::Le, Value::UInt(a), Value::UInt(b)) => Value::Bool(a <= b),
                (BinaryOp::Gt, Value::UInt(a), Value::UInt(b)) => Value::Bool(a > b),
                (BinaryOp::Ge, Value::UInt(a), Value::UInt(b)) => Value::Bool(a >= b),
                (BinaryOp::And, Value::Bool(a), Value::Bool(b)) => Value::Bool(a && b),
                (BinaryOp::Or, Value::Bool(a), Value::Bool(b)) => Value::Bool(a || b),
                _ => return Err(failure("type", "Invalid operand types.")),
            }
        }
    };
    cache[i] = Some(result.clone());
    Ok(result)

fn execute_statement(
    program: &Program,
    stmt: &Statement,
    env: &mut BTreeMap<String, Value>,
    current: &mut Snapshot,
    meter: &mut Option<&mut Meter>,
    effects: &mut Vec<Effect>,
) -> Result<Option<Value>, Error> {
    charge_logical(meter)?;
    match stmt {
        Statement::Await { guard, .. } => {
            let v = evaluate(program, *guard, env, current, meter)?;
            Ok(Some(v))
        }
        Statement::Let { name, value } => {
            let v = evaluate(program, *value, env, current, meter)?;
            env.insert(name.clone(), v.clone());
            Ok(Some(v))
        }
        Statement::Requires { predicate } | Statement::Ensures { predicate } => {
            let v = evaluate(program, *predicate, env, current, meter)?;
            if v != Value::Bool(true) {
                return Err(failure(
                    if matches!(stmt, Statement::Requires { .. }) {
                        "requires"
                    } else {
                        "ensures"
                    },
                    "Action predicate evaluated to false.",
                ));
            }
            Ok(Some(v))
        }
        Statement::Next { state, value } => {
            let after = evaluate(program, *value, env, current, meter)?;
            let before = current.state[state].clone();
            current.state.insert(state.clone(), after.clone());
            env.insert(state.clone(), after.clone());
            effects.push(Effect::State {
                name: state.clone(),
                before,
                after: after.clone(),
            });
            Ok(Some(after))
        }
        Statement::Emit { name, value } => {
            let v = evaluate(program, *value, env, current, meter)?;
            effects.push(Effect::Emit {
                name: name.clone(),
                value: v.clone(),
            });
            Ok(Some(v))
